<?php require __DIR__.'/app.php';render_header($product?$product['name']:'Không tìm thấy sản phẩm','sanpham');if(!$product):?><div class="empty-state">Không tìm thấy sản phẩm. <a href="index.php?page=sanpham">Quay lại</a></div><?php else:?><div class="breadcrumb"><a href="index.php">Trang chủ</a> / <?=e($product['category_name'])?></div><section class="detail-layout"><div class="detail-image"><img src="<?=e(image_url($product))?>" alt="<?=e($product['name'])?>"></div><div class="detail-copy"><span class="eyebrow"><?=e($product['brand'])?> · <?=e($product['category_name'])?></span><h1><?=e($product['name'])?></h1><p><?=e($product['description'])?></p><div class="price detail-price"><strong><?=money($product['sale_price'])?></strong><?php if($product['sale_price']<$product['list_price']):?><del><?=money($product['list_price'])?></del><?php endif;?></div><div class="specs"><?php foreach(explode('|',$product['specs']) as $spec):?><span><?=e($spec)?></span><?php endforeach;?></div><form method="post" action="index.php?page=them_gio" class="add-form" data-cart-add data-cart-add><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="product_id" value="<?=(int)$product['id']?>"><label>Số lượng<input type="number" name="quantity" value="1" min="1" max="99"></label><button class="button button-orange">Thêm vào giỏ</button></form><p class="subtle">Bảo hành chính hãng · Hỗ trợ đổi trả theo chính sách cửa hàng</p></div></section><section class="section"><h2>Đánh giá sản phẩm</h2><p class="rating"><?=number_format((float)($rating['average']??0),1)?> / 5 <small>(<?=(int)($rating['count']??0)?> đánh giá)</small></p><?php foreach($reviews as $r):?><article class="review"><b><?=e($r['user_name'])?></b><span><?=$r['stars']?> / 5</span><p><?=e($r['comment'])?></p></article><?php endforeach;?><?php if(user()):?><p>Chỉ khách đã nhận hàng mới có thể gửi đánh giá. Mở <a href="index.php?page=taikhoan">Đơn hàng của tôi</a> để đánh giá sản phẩm.</p><?php else:?><p><a href="index.php?page=dangnhap">Đăng nhập</a> để theo dõi đơn hàng và gửi đánh giá sau khi nhận hàng.</p><?php endif;?></section><?php endif;?><?php render_footer();?>